List<int> Filter(List<int> items, Func<int, bool> keep)
{
    var result = new List<int>();
    foreach (var item in items)
        if (keep(item)) result.Add(item);
    return result;
}

List<int> numbers = [1, 2, 3, 4, 5, 6];
